set
  title = 'Motor Control / Neural Control of Movement',
  goal = 'Motor Control / Neural Control of Movement',
  summary = 'This course examines how the nervous system controls human movement. Students study nervous system organization, neural signaling, sensory integration, motor neurons and motor units, reflexes, central pattern generators, voluntary movement, cortical motor control, cerebellar and basal ganglia function, posture, balance, gait, neuromechanics, EMG and movement measurement, motor learning and plasticity, development, aging, fatigue, motor disorders, rehabilitation, sport performance, and applied case reasoning.',
  data = $mcncmjson${"slug": "motor-control-neural-control-of-movement", "title": "Motor Control / Neural Control of Movement", "description": "This course examines how the nervous system controls human movement. Students study nervous system organization, neural signaling, sensory integration, motor neurons and motor units, reflexes, central pattern generators, voluntary movement, cortical motor control, cerebellar and basal ganglia function, posture, balance, gait, neuromechanics, EMG and movement measurement, motor learning and plasticity, development, aging, fatigue, motor disorders, rehabilitation, sport performance, and applied case reasoning.", "topics": [{"id": "2a1f4b88-8947-4d69-b520-29179243cc14", "type": "topic", "title": "Nervous System Organization for Movement", "description": "Establish the neural architecture that makes perception, action, posture, and skilled movement possible.", "children": [{"id": "2fc581e6-48fc-4904-9286-4e172419dc55", "type": "subtopic", "title": "Functional hierarchy", "description": "Students learn how spinal, brainstem, subcortical, cerebellar, and cortical systems cooperate rather than act alone.", "children": [{"id": "5defd8af-a8ce-411c-9b74-8b455c35b265", "type": "concept", "title": "Spinal cord"}, {"id": "464a145c-86e4-4c8f-ba35-c739037fc38e", "type": "concept", "title": "Brainstem"}, {"id": "8e25f3e5-dfd7-440d-bb23-b36df71ad378", "type": "concept", "title": "Cerebellum"}, {"id": "7a17e6e0-b4d0-47aa-8cbd-01f086a5e42e", "type": "concept", "title": "Basal ganglia and cerebral cortex"}]}, {"id": "fb258776-0f3f-4498-96bd-fd7330927206", "type": "subtopic", "title": "Motor system goals", "description": "Movement control is organized around action, posture, prediction, adaptation, and survival.", "children": [{"id": "b5001cf9-ee19-4d95-9c71-92ad6b0e2fe3", "type": "concept", "title": "Posture and balance"}, {"id": "7dc8dc59-6803-4d22-9b58-0ce5adab9b0a", "type": "concept", "title": "Locomotion"}, {"id": "00b8517c-adbf-4350-94d9-6