concept", "title": "Posterior parietal contributions"}]}, {"id": "afe3cfcd-e0d8-499a-ae98-bc9b1cc31b7a", "type": "subtopic", "title": "Motor maps and plasticity", "description": "Cortical representation changes with use, injury, and learning.", "children": [{"id": "5d297bc3-d51b-4b90-8518-17db0d82b5ff", "type": "concept", "title": "Somatotopy"}, {"id": "87e4cc83-fdee-4b6d-beff-52b03662a69f", "type": "concept", "title": "Use-dependent plasticity"}, {"id": "c6bd7c6b-5ff0-4661-9546-b67b1a106c38", "type": "concept", "title": "Skill learning"}, {"id": "bf11b172-2b7f-4df5-b492-50cc1ca21455", "type": "concept", "title": "Recovery after injury"}]}, {"id": "9bd317fd-3a7e-4164-9dd5-ab9948c39233", "type": "subtopic", "title": "Corticospinal control", "description": "Students connect cortical output to fine voluntary movement.", "children": [{"id": "1f61469d-4701-40c2-b7e2-318cb121c446", "type": "concept", "title": "Distal limb control"}, {"id": "bde97578-13d6-44b2-9bdb-622606747846", "type": "concept", "title": "Fractionated movement"}, {"id": "59a66ad1-883b-43b6-9706-253c30f9a86d", "type": "concept", "title": "Upper motor neuron signs"}, {"id": "baf90ffe-dae2-404b-90cf-cd95c0763291", "type": "concept", "title": "Laterality"}]}]}, {"id": "5ac48909-7f79-4699-b97d-aeea3336ad91", "type": "topic", "title": "Cerebellum, Basal Ganglia, and Error-Based Control", "description": "Compare the neural systems that tune coordination, timing, prediction, habit, and action selection.", "children": [{"id": "9501e792-50b1-4e6d-8842-ce78668a1408", "type": "subtopic", "title": "Cerebellar control", "description": "Students learn how the cerebellum supports prediction, coordination, timing, and error correction.", "children": [{"id": "bd7e49d5-69e2-4cfe-8e19-42a71fec16a9", "type": "concept", "title": "Forward models"}, {"id": "988d52ca-bfe4-4c2e-a804-7e9665b876a4", "type": "concept", "title": "Timing"}, {"id": "cf9ca9db-1323-48ca-a644-2c88502bed11", "type": "concept", "title": "Motor adaptation"}